css:
.d-sc{box-sizing:border-box;width:300px;max-width:100%;height:150px;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--bg)}
.d-sc-scroll{box-sizing:border-box;height:100%;overflow-y:auto;scrollbar-width:none;padding:0 12px 12px}
.d-sc-scroll::-webkit-scrollbar{width:0;height:0}
.d-sc-head{position:sticky;top:0;display:flex;gap:8px;padding:12px 0 8px;background:var(--bg);border-bottom:1px solid var(--line)}
.d-sc-cell{flex:1;display:flex;flex-direction:column;gap:2px}
.d-sc-num{font-family:var(--font-mono);font-size:var(--fs-21);font-weight:650;line-height:var(--lh-display);color:var(--ink);font-variant-numeric:tabular-nums}
.d-sc-k{font-size:var(--fs-11);letter-spacing:var(--tracking-mono-label);color:var(--faint)}
.d-sc-p{margin:12px 0 0;font-size:var(--fs-11);line-height:var(--lh-note);color:var(--muted)}
@property --d-sc-n1{syntax:"<integer>";inherits:false;initial-value:0}
@property --d-sc-n2{syntax:"<integer>";inherits:false;initial-value:0}
@property --d-sc-n3{syntax:"<integer>";inherits:false;initial-value:0}
.d-sc-n1{--d-sc-n1:0;counter-reset:d-sc-c1 var(--d-sc-n1);animation:d-scroll-counters-one steps(6) both;animation-timeline:scroll(nearest)}
.d-sc-n2{--d-sc-n2:0;counter-reset:d-sc-c2 var(--d-sc-n2);animation:d-scroll-counters-two steps(6) both;animation-timeline:scroll(nearest)}
.d-sc-n3{--d-sc-n3:0;counter-reset:d-sc-c3 var(--d-sc-n3);animation:d-scroll-counters-three steps(6) both;animation-timeline:scroll(nearest)}
.d-sc-n1::before{content:counter(d-sc-c1)}
.d-sc-n2::before{content:counter(d-sc-c2)}
.d-sc-n3::before{content:counter(d-sc-c3) "%"}
.d-sc-scroll:focus-visible{outline:1px solid var(--ink);outline-offset:-3px}
@keyframes d-scroll-counters-one{from{--d-sc-n1:0}to{--d-sc-n1:126}}
@keyframes d-scroll-counters-two{from{--d-sc-n2:0}to{--d-sc-n2:18}}
@keyframes d-scroll-counters-three{from{--d-sc-n3:0}to{--d-sc-n3:96}}
